import numpy as np
from scipy.optimize import least_squares
V=np.var(dP_dt)
forms={
 'a P^b/(1+cP^d)': (lambda p: p[0]*P**p[1]/(1+p[2]*P**p[3]), [5,0.5,0.5,1]),
 'a P^b - c P^d': (lambda p: p[0]*P**p[1]-p[2]*P**p[3], [5,0.5,0.1,2]),
 'a P^b exp(-cP)': (lambda p: p[0]*P**p[1]*np.exp(-p[2]*P), [5,0.5,0.1]),
 'a P^b (1-P/K)': (lambda p: p[0]*P**p[1]*(1-P/p[2]), [5,0.5,9]),
 'a P^b /(1+cP)+d': (lambda p: p[0]*P**p[1]/(1+p[2]*P)+p[3], [5,0.5,0.5,0]),
 'a*(1-exp(-bP^c))': (lambda p: p[0]*(1-np.exp(-p[1]*P**p[2])), [9,1,0.5]),
}
for k,(f,p0) in forms.items():
    try:
        r=least_squares(lambda p: f(p)-dP_dt,p0,max_nfev=5000)
        print(k, np.round(r.x,4), '%.2e'%(np.mean(r.fun**2)/V))
    except Exception as e: print(k,e)
